def age_band(age, edges=(0, 18, 35, 60, 100)):
    """Return the (low, high] band label for age, or None if outside."""
    for low, high in zip(edges, edges[1:]):
        if low < age <= high:
            return f'({low}, {high}]'
    return None

ages = [16, 18, 22, 47, 70]
print([age_band(a) for a in ages])
# ['(0, 18]', '(0, 18]', '(18, 35]', '(35, 60]', '(60, 100]']

