def find_bin(value, edges):
    for i in range(len(edges) - 1):
        if edges[i] < value <= edges[i + 1]:
            return i
    return None

edge_text = [t.strip() for t in input().split(',')]
edges = [float(t) for t in edge_text]
line = input().strip()
values = [float(t) for t in line.split(',')] if line else []

counts = [0] * (len(edges) - 1)
outside = 0
for v in values:
    i = find_bin(v, edges)
    if i is None:
        outside += 1
    else:
        counts[i] += 1

for i, c in enumerate(counts):
    print(f'({edge_text[i]}, {edge_text[i + 1]}]: {c}')
print(f'out of range: {outside}')

